  const rcRenderPrevious=render;
  render=function(){
    if(role==='owner'&&module==='whole'&&page==='nw-finance'){if(!rc.loaded&&!rc.loading)queueMicrotask(()=>rcLoad());renderNav();$('#roleSelect').value=role;$('#view').innerHTML=rc.loading?head('整装台账','云端财务','正在加载…')+rcStatus():rcFinancePage();return}
    if(role==='owner'&&module==='whole'&&page==='reno-quote-editor'){if(!rc.loaded&&!rc.loading)queueMicrotask(()=>rcLoad());renderNav();$('#roleSelect').value=role;$('#view').innerHTML=rc.loading?head('整装报价','正在加载报价数据…','')+rcStatus():rcQuoteEditorPage();if(rc.loaded){rcRestoreDraft();rcQuoteTotals($('#foRenoQuoteForm'));document.querySelectorAll('#foRenoQuoteForm [data-rc-note]').forEach(x=>{x.style.height='auto';x.style.height=x.scrollHeight+'px'})}return}
    if(role==='owner'&&module==='whole'&&page==='customer-detail'){renderNav();$('#roleSelect').value=role;$('#view').innerHTML=rcCustomerPage();if(rc.selectedCustomer&&!rc.profileLoading&&rc.profile?.customer_id!==rc.selectedCustomer)queueMicrotask(()=>rcLoadProfile(rc.selectedCustomer));return}
    if(role==='owner'&&module==='whole'&&page==='reno-order-detail'){renderNav();$('#roleSelect').value=role;$('#view').innerHTML=rcOrderPage();return}
    rcRenderPrevious();if(role==='owner'&&module==='whole'&&!['modules'].includes(page)&&!rc.loaded&&!rc.loading)queueMicrotask(()=>rcLoad());
  };
  function rcPageGo(target){page=target;module='whole';render()}
