  async function rcUploadPrivate(orderId,kind,file){if(!file||file.size===0)return null;if(file.size>20971520)throw Error('附件不能超过20MB');const order=rcOrder(orderId),customer=rcCustomer(order?.customer_id);if(!customer)throw Error('找不到附件对应客户');const date=new Date().toISOString().slice(0,10),safe=file.name.replace(/[^a-zA-Z0-9._-]/g,'_'),path=`reno/${customer.id}/${order.id}/${kind}/${date}/${crypto.randomUUID()}-${safe}`,client=rcClient(),{error}=await client.storage.from('reno-files').upload(path,file,{contentType:file.type,upsert:false});if(error)throw error;return path}
