    if(name==='rc-stage-edit'){const c=rcCustomer(id);if(!c)return;rcOpenForm('更新客户阶段','foRenoCustomerStageForm',`<input type="hidden" name="customer_id" value="${id}"><label>业务状态<select class="field" name="status">${['线索','量房','报价中','已签约','施工中','已完工','已结算','搁置'].map(x=>`<option ${x===c.business_status?'selected':''}>${x}</option>`).join('')}</select></label><label>当前阶段<input class="field" name="stage" value="${esc(c.stage||'')}"></label>`,'保存阶段');return}
